adminPlatformRouter.post('/announcements',requirePermission('announcements.manage'),async(req,res)=>{const body=parseBody(z.object({title:z.string().trim().min(3).max(140),message:z.string().trim().min(5).max(5000),status:z.enum(['draft','published']).default('draft')}),req.body);const row=await Announcement.create({...body,author:req.user._id,createdAt:new Date(),updatedAt:new Date()});await writeAudit({actor:req.user._id,action:'announcement.created',resource:'announcement',resourceId:String(row._id)});return sendData(res,{id:String(row._id),title:row.title,message:row.message,status:row.status},201);});
adminPlatformRouter.get('/faqs',async(_req,res)=>{const rows=await FAQ.find({isActive:{$ne:false}}).sort({createdAt:1});return sendData(res,{faqs:rows.map((x:any)=>({id:String(x._id),question:x.question,answer:x.answer}))});});
adminPlatformRouter.get('/reports',requirePermission('reports.read'),async(req,res)=>{const {page,limit,skip}=pagination(req.query as Record<string,unknown>);const filter:any={};if(req.query.status)filter.status=String(req.query.status);const search=String(req.query.search??'').trim().slice(0,80);if(search){const expression={$regex:safeRegex(search),$options:'i'};filter.$or=[{type:expression},{reason:expression}];}const [rows,total]=await Promise.all([Report.find(filter).sort({createdAt:-1}).skip(skip).limit(limit),Report.countDocuments(filter)]);const reporterIds=rows.map((x:any)=>x.reporter).filter((id:any)=>id&&mongoose.Types.ObjectId.isValid(String(id)));const reporters=reporterIds.length?await User.find({_id:{$in:reporterIds}}).select('fullName firstName lastName email').lean():[];const reporterById=new Map(reporters.map((u:any)=>[String(u._id),u]));return sendList(res,rows.map((x:any)=>{const reporter:any=reporterById.get(String(x.reporter));const fullName=(reporter?.fullName??reporter?.name??[reporter?.firstName,reporter?.lastName].filter(Boolean).join(' '))||null;return{id:String(x._id),_id:String(x._id),type:x.type,reason:x.reason,status:x.status??'submitted',resolution:x.resolution??null,orderId:x.order?String(x.order):null,reporter:reporter?{id:String(reporter._id),fullName:fullName||reporter.email||null,email:reporter.email??null}:null,reporterId:x.reporter?String(x.reporter):null,createdAt:x.createdAt??null};}),page,limit,total);});
adminPlatformRouter.patch('/reports/:id',requirePermission('support.manage'),async(req,res)=>{const id=objectId(req.params.id);const body=parseBody(z.object({status:z.enum(['under_review','resolved','rejected']),resolution:z.string().trim().min(5).max(1000)}),req.body);const row=await Report.findByIdAndUpdate(id,{$set:{...body,handledBy:req.user._id,updatedAt:new Date()}},{returnDocument:'after'});if(!row)throw new HttpError(404,'Report not found.','REPORT_NOT_FOUND');await writeAudit({actor:req.user._id,action:'report.updated',resource:'report',resourceId:String(id),metadata:{status:body.status}});return sendData(res,{id:String(row._id),status:row.status,resolution:row.resolution});});
